import{_ as i,o as s,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Crimson/Seastar OSD Meeting 2018-11-27","description":"","frontmatter":{"title":"Crimson/Seastar OSD Meeting 2018-11-27","date":"2018-11-27T00:00:00.000Z","updated":"2018-11-29T00:00:00.000Z","tags":["Ceph","OSD","会议纪要","分布式存储","开源项目"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Crimson_Seastar_OSD_Meeting_2018-11-27.md","filePath":"posts/2018/Crimson_Seastar_OSD_Meeting_2018-11-27.md","lastUpdated":1780460162000}'),r={name:"posts/2018/Crimson_Seastar_OSD_Meeting_2018-11-27.md"};function l(e,t,a,g,p,u){return s(),o("div",null,[...t[0]||(t[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年11月27日</p><p><strong>参会人员</strong>： Tomas Michaud、Jim、John、Justice、Reed Oak、Tom等</p><p><strong>会议主题</strong>： 讨论Ceph项目进展、问题解决及后续行动计划</p><p><strong>会议内容</strong>：</p><p><strong>1. Ceph项目进展</strong></p><ul><li><strong>Tomas Michaud</strong>： 由于上周是感恩节假期，项目进展不多。他完成了一些配置保存的工作，并上传了补丁。</li><li><strong>John</strong>： 尚未完成工作进度，但已上传配置保存的补丁。</li><li><strong>Tomas Michaud</strong>： 推出了Mendel TC的原型，并上传到GitHub。</li><li><strong>Justice</strong>： 正在编写内存测试用例，并更新POSIX线程中的翻译。</li><li><strong>Reed Oak</strong>： 由于专注于Luminos中的febs问题，上周进展不多。</li><li><strong>Tom</strong>： 正在解决Ceph目录结构中公共和私有头文件依赖问题。</li></ul><p><strong>2. 问题解决</strong></p><ul><li><strong>Jim</strong>： 对Crimson PR的审查速度较慢，Tomas Michaud已发送邮件询问原因。</li><li><strong>Tom</strong>： 在Crimson PR中遇到了一些问题，正在尝试解决。</li><li><strong>Reed Oak</strong>： 正在解决Luminos中buffer list的依赖问题。</li></ul><p><strong>3. 后续行动计划</strong></p><ul><li><strong>Tomas Michaud</strong>： 修订消息传递构造函数和模拟投资，并将其集成到驱动程序中。</li><li><strong>John</strong>： 完成配置保存的工作。</li><li><strong>Justice</strong>： 继续编写内存测试用例，并更新POSIX线程中的翻译。</li><li><strong>Reed Oak</strong>： 解决Luminos中buffer list的依赖问题。</li><li><strong>Tom</strong>： 解决Ceph目录结构中公共和私有头文件依赖问题。</li></ul><p><strong>4. 其他事项</strong></p><ul><li>会议中提到，一些工作进度已被移除，因为它们在Nautilus T发布前需要进一步审查。</li><li>会议结束时，大家表示期待下周的会议。</li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph</li><li>Mendel TC</li><li>Crimson PR</li><li>Luminos</li><li>POSIX线程</li><li>buffer list</li><li>Nautilus T</li><li>会议纪要</li><li>OSD</li><li>分布式存储</li><li>开源项目</li></ul>',15)])])}const d=i(r,[["render",l]]);export{m as __pageData,d as default};
